import AVFoundation
import Observation
import Synchronization

/// The synth as the UI sees it. `patch` holds the whole sound; the UI reads and writes it,
/// and every change is forwarded to the audio thread through a lock-free queue. The sound
/// itself is generated by `SynthDSP` inside an `AVAudioSourceNode`.
@Observable
final class SynthEngine {
    var patch = SynthPatch() {
        didSet { sendChanges() }
    }
    /// The drum machine: global app state, kept across launches and never changed by presets.
    var drums = DrumKitStore.load() {
        didSet {
            sendChanges()
            scheduleDrumSave()
        }
    }
    private(set) var errorMessage: String?
    private(set) var isPlaying = false

    /// Shared with the audio thread, which reports the playing step through it.
    @ObservationIgnored let monitor = SynthMonitor()
    /// Step notes the audio thread has been told about.
    /// Steps of all banks (bank * 16 + step) the audio thread has been told about.
    @ObservationIgnored private var sentSteps: [Int?] = []
    /// Drum patterns of all banks the audio thread has been told about.
    @ObservationIgnored private var sentDrumBanks: [[[Bool]]] = []

    /// Parameter values the audio thread has been told about, to send only what changed.
    @ObservationIgnored private var sentValues: [Float] = []

    /// Created in `start()`: SwiftUI may build this object more than once, and only the kept
    /// instance should own audio hardware.
    @ObservationIgnored private var engine: AVAudioEngine?
    @ObservationIgnored private let queue = SynthEventQueue()
    /// Events from MIDI controllers; its only producer is the MIDI input queue.
    @ObservationIgnored let midiQueue = SynthEventQueue()
    @ObservationIgnored private var dsp: SynthDSP?
    @ObservationIgnored private var configurationObserver: (any NSObjectProtocol)?
    @ObservationIgnored private var drumSaveTask: Task<Void, Never>?

    func value(_ param: SynthParam) -> Float {
        audioValue(param, patch: patch, drums: drums)
    }

    func set(_ param: SynthParam, _ newValue: Float) {
        if param.isDrumParam {
            drums.setValue(newValue, for: param)
        } else {
            patch.setValue(newValue, for: param)
        }
    }

    /// Saves the drum kit shortly after the last change (a knob drag makes many changes).
    private func scheduleDrumSave() {
        drumSaveTask?.cancel()
        drumSaveTask = Task { [weak self] in
            try? await Task.sleep(for: .milliseconds(400))
            guard !Task.isCancelled, let self else { return }
            DrumKitStore.save(self.drums)
        }
    }

    /// Writes the drum kit now (e.g. when the app goes to the background).
    func saveDrumsNow() {
        drumSaveTask?.cancel()
        DrumKitStore.save(drums)
    }

    /// Pushes every parameter that differs from what the audio thread already has.
    private func sendChanges() {
        guard !sentValues.isEmpty else { return } // not started yet; `start()` sends everything
        for param in SynthParam.allCases {
            let value = audioValue(param, patch: patch, drums: drums)
            if value != sentValues[param.rawValue] {
                sentValues[param.rawValue] = value
                queue.push(SynthEvent(kind: .parameter, index: Int32(param.rawValue), value: value))
            }
        }
        for (slot, note) in patch.sequencer.banks.joined().enumerated() where sentSteps.indices.contains(slot) && sentSteps[slot] != note {
            sentSteps[slot] = note
            queue.push(SynthEvent(kind: .stepNote, index: Int32(slot), value: Float(note ?? -1)))
        }
        if drums.banks != sentDrumBanks, sentDrumBanks.count == SynthPatch.bankCount {
            for bank in 0..<SynthPatch.bankCount where drums.banks[bank] != sentDrumBanks[bank] {
                for drum in 0..<DrumKind.count {
                    for step in 0..<SynthPatch.stepCount where drums.banks[bank][drum][step] != sentDrumBanks[bank][drum][step] {
                        let on = drums.banks[bank][drum][step]
                        let slot = (bank * DrumKind.count + drum) * SynthPatch.stepCount + step
                        queue.push(SynthEvent(kind: .drumStep, index: Int32(slot), value: on ? 1 : 0))
                    }
                }
            }
            sentDrumBanks = drums.banks
        }
    }

    func noteOn(_ note: Int, velocity: Float = 0.8) {
        queue.push(SynthEvent(kind: .noteOn, index: Int32(note), value: velocity))
    }

    func noteOff(_ note: Int) {
        queue.push(SynthEvent(kind: .noteOff, index: Int32(note), value: 0))
    }

    func allNotesOff() {
        queue.push(SynthEvent(kind: .allNotesOff, index: 0, value: 0))
        if !keyModeKeys.isEmpty {
            keyModeKeys.removeAll()
            if !patch.sequencer.hold { isPlaying = false }
        }
    }

    // MARK: - Keyboard

    /// Keys held in transpose/arp mode, mirrored from the audio thread's rules so the
    /// Play light follows: a key press starts the pattern, releasing all keys stops it (unless Hold).
    @ObservationIgnored private var keyModeKeys: Set<Int> = []

    /// A key on the on-screen keyboard went down. What it does depends on Key mode:
    /// Off plays the note; Transpose and Arp drive the sequencer.
    func keyDown(_ note: Int, velocity: Float = 0.8) {
        queue.push(SynthEvent(kind: .keyDown, index: Int32(note), value: velocity))
        mirrorKey(note, down: true)
    }

    func keyUp(_ note: Int) {
        queue.push(SynthEvent(kind: .keyUp, index: Int32(note), value: 0))
        mirrorKey(note, down: false)
    }

    /// Keeps the Play light in step with keys that drive the sequencer (screen or MIDI;
    /// MIDI notes reach the audio thread directly and only call this).
    func mirrorKey(_ note: Int, down: Bool) {
        if down {
            if patch.sequencer.keyMode != .off, patch.sequencer.enabled {
                keyModeKeys.insert(note)
                isPlaying = true
            }
        } else if keyModeKeys.remove(note) != nil, keyModeKeys.isEmpty, !patch.sequencer.hold {
            isPlaying = false
        }
    }

    // MARK: - Sequencer

    func play() {
        queue.push(SynthEvent(kind: .play, index: 0, value: 0))
        isPlaying = true
    }

    func stop() {
        queue.push(SynthEvent(kind: .stop, index: 0, value: 0))
        isPlaying = false
    }

    /// Step being played right now (read from the audio thread), or nil.
    var currentStep: Int? {
        let step = monitor.currentStep.load(ordering: .relaxed)
        return step >= 0 ? step : nil
    }

    /// Bank the audio thread is playing (it can lag the selection until the pattern ends).
    var playingBank: Int { monitor.playingBank.load(ordering: .relaxed) }
    /// A track switched on during playback that waits for the next bar.
    var sequencerArmed: Bool { monitor.sequencerArmed.load(ordering: .relaxed) != 0 }
    var drumsArmed: Bool { monitor.drumsArmed.load(ordering: .relaxed) != 0 }

    // MARK: - Banks

    /// Steps copied from a bank (Copy / Paste), not part of the sound.
    var bankClipboard: [Int?]?

    func selectBank(_ bank: Int) {
        guard (0..<SynthPatch.bankCount).contains(bank) else { return }
        patch.sequencer.activeBank = bank
    }

    func bankSteps(_ bank: Int) -> [Int?] {
        patch.sequencer.banks.indices.contains(bank) ? patch.sequencer.banks[bank] : SynthPatch.Sequencer.emptyBank
    }

    func setBankSteps(_ bank: Int, _ steps: [Int?]) {
        guard patch.sequencer.banks.indices.contains(bank) else { return }
        var padded = Array(steps.prefix(SynthPatch.stepCount))
        padded += Array(repeating: nil, count: SynthPatch.stepCount - padded.count)
        patch.sequencer.banks[bank] = padded
    }

    // MARK: - Pattern presets

    /// Loads a preset that carries a whole groove (sequencer banks, tempo and drums). The sound
    /// changes at once; while playing, the sequencer banks, the tempo and the drum banks are
    /// staged on the audio thread and all swap in on step 1 of the next bar (at once when stopped).
    func loadPattern(_ newPatch: SynthPatch, drums kit: DrumKit?) {
        var newPatch = newPatch
        newPatch.drumKit = nil
        let kit = kit?.sanitized()
        if !sentValues.isEmpty {
            let notes = Array(newPatch.sequencer.banks.joined())
            for (slot, note) in notes.enumerated() {
                queue.push(SynthEvent(kind: .stagedStepNote, index: Int32(slot), value: Float(note ?? -1)))
            }
            sentSteps = notes
            if let kit, sentDrumBanks.count == SynthPatch.bankCount {
                for bank in 0..<SynthPatch.bankCount {
                    for drum in 0..<DrumKind.count {
                        for step in 0..<SynthPatch.stepCount {
                            let slot = (bank * DrumKind.count + drum) * SynthPatch.stepCount + step
                            queue.push(SynthEvent(kind: .stagedDrumStep, index: Int32(slot), value: kit.banks[bank][drum][step] ? 1 : 0))
                        }
                    }
                }
                sentDrumBanks = kit.banks
            }
            let tempo = audioValue(.seqTempo, patch: newPatch, drums: drums)
            sentValues[SynthParam.seqTempo.rawValue] = tempo // goes with the pattern, not right away
            queue.push(SynthEvent(kind: .commitPattern, index: kit == nil ? 0 : 1, value: tempo))
        }
        patch = newPatch // sends the sound settings and the bank choice
        if let kit { drums = kit }
    }

    // MARK: - Drum banks

    /// Replaces the whole drum machine with one saved in a preset. Sounds change at once; all
    /// banks are staged on the audio thread and swap in, together with the active bank, on
    /// step 1 of the next bar while playing (at once when stopped).
    func loadDrums(_ kit: DrumKit) {
        let kit = kit.sanitized()
        if sentDrumBanks.count == SynthPatch.bankCount {
            for bank in 0..<SynthPatch.bankCount {
                for drum in 0..<DrumKind.count {
                    for step in 0..<SynthPatch.stepCount {
                        let slot = (bank * DrumKind.count + drum) * SynthPatch.stepCount + step
                        queue.push(SynthEvent(kind: .stagedDrumStep, index: Int32(slot), value: kit.banks[bank][drum][step] ? 1 : 0))
                    }
                }
            }
            queue.push(SynthEvent(kind: .commitDrumSteps, index: 0, value: 0))
            sentDrumBanks = kit.banks // so `sendChanges` doesn't also send them as instant edits
        }
        drums = kit // sends the sound settings and the active bank, and saves the kit
    }

    /// Drum bank the audio thread is playing (it can lag the selection until the bar ends).
    var playingDrumBank: Int { monitor.playingDrumBank.load(ordering: .relaxed) }

    /// Drum steps copied from a bank (Copy / Paste); separate from the sequencer clipboard.
    var drumBankClipboard: [[Bool]]?

    func selectDrumBank(_ bank: Int) {
        guard (0..<SynthPatch.bankCount).contains(bank) else { return }
        drums.activeBank = bank
    }

    func drumBankPattern(_ bank: Int) -> [[Bool]] {
        drums.banks.indices.contains(bank) ? drums.banks[bank] : DrumKit.emptyPattern
    }

    func setDrumBankPattern(_ bank: Int, _ pattern: [[Bool]]) {
        guard drums.banks.indices.contains(bank) else { return }
        var padded = DrumKit.emptyPattern
        for (row, steps) in pattern.prefix(DrumKind.count).enumerated() {
            for (step, on) in steps.prefix(SynthPatch.stepCount).enumerated() { padded[row][step] = on }
        }
        drums.banks[bank] = padded
    }

    /// Drum step being played right now (read from the audio thread), or nil.
    var currentDrumStep: Int? {
        let step = monitor.currentDrumStep.load(ordering: .relaxed)
        return step >= 0 ? step : nil
    }

    /// Plays one hit of a drum's current sound (after choosing a variant).
    func previewDrum(_ drum: DrumKind) {
        queue.push(SynthEvent(kind: .drumPreview, index: Int32(drum.rawValue), value: 0))
    }

    /// Switches a drum to another sound variant: its decay jumps to the variant's natural
    /// length (each variant has its own decay range) and the drum plays once as a preview.
    /// Level and tune are kept.
    func setDrumVariant(_ drum: DrumKind, _ variant: Int) {
        let v = (variant % DrumVariants.count + DrumVariants.count) % DrumVariants.count
        var kit = drums
        kit[drum].variant = v
        kit[drum].decay = DrumVariants.defaultDecay(drum, v)
        drums = kit // one change, so the audio thread gets variant and decay together
        previewDrum(drum)
    }

    func toggleDrumStep(_ drum: DrumKind, _ step: Int) {
        guard drums.pattern.indices.contains(drum.rawValue),
              drums.pattern[drum.rawValue].indices.contains(step) else { return }
        drums.pattern[drum.rawValue][step].toggle()
    }


    /// Writes `note` into a step, or clears the step if it already holds that note.
    func toggleStep(_ step: Int, note: Int) {
        guard patch.sequencer.steps.indices.contains(step) else { return }
        patch.sequencer.steps[step] = patch.sequencer.steps[step] == note ? nil : note
    }

    func start() {
        guard dsp == nil else { return }
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.playback, mode: .default)
            // ~10 ms: still feels instant on the keys, with room to spare for unoptimised Debug builds.
            try session.setPreferredIOBufferDuration(0.01)
            try session.setActive(true)

            let engine = AVAudioEngine()
            let outputRate = engine.outputNode.outputFormat(forBus: 0).sampleRate
            let sampleRate = outputRate > 0 ? outputRate : 48_000
            sentValues = SynthParam.allCases.map { audioValue($0, patch: patch, drums: drums) }
            sentSteps = Array(patch.sequencer.banks.joined())
            sentDrumBanks = drums.banks
            let dsp = SynthDSP(sampleRate: sampleRate, queue: queue, midiQueue: midiQueue, monitor: monitor,
                               initialValues: sentValues, initialSteps: sentSteps.map { $0 ?? -1 },
                               initialDrumSteps: sentDrumBanks.flatMap { $0.flatMap { $0 } })
            guard let format = AVAudioFormat(standardFormatWithSampleRate: sampleRate, channels: 2) else { return }

            let source = AVAudioSourceNode(format: format, renderBlock: Self.makeRenderBlock(dsp: dsp))
            engine.attach(source)
            engine.connect(source, to: engine.mainMixerNode, format: format)
            try engine.start()
            self.engine = engine
            self.dsp = dsp

            // Headphones plugged in/out etc. stop the engine; start it again.
            configurationObserver = NotificationCenter.default.addObserver(
                forName: .AVAudioEngineConfigurationChange, object: engine, queue: .main
            ) { [weak self] _ in
                MainActor.assumeIsolated { try? self?.engine?.start() }
            }
        } catch {
            errorMessage = String(localized: "Sound couldn’t start: \(error.localizedDescription)")
        }
    }

    /// Built outside the main actor so the closure isn't tied to the main thread; it only
    /// calls into `SynthDSP`, which does no allocation, locking or I/O.
    private nonisolated static func makeRenderBlock(dsp: SynthDSP) -> AVAudioSourceNodeRenderBlock {
        { _, _, frameCount, audioBufferList in
            let buffers = UnsafeMutableAudioBufferListPointer(audioBufferList)
            guard let left = buffers.first?.mData?.assumingMemoryBound(to: Float.self) else { return noErr }
            // Deinterleaved stereo: the second buffer is the right channel (mono falls back to left).
            let right = buffers.count > 1 ? buffers[1].mData?.assumingMemoryBound(to: Float.self) ?? left : left
            dsp.render(frameCount: Int(frameCount), left: left, right: right)
            return noErr
        }
    }
}

/// Saves and loads the drum kit as JSON in Application Support, separate from presets.
nonisolated enum DrumKitStore {
    static var url: URL {
        let support = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return support.appendingPathComponent("DrumKit.json")
    }

    /// The saved kit, or a fresh one (empty pattern) if there is none or it can't be read.
    static func load() -> DrumKit {
        guard let data = try? Data(contentsOf: url),
              let kit = try? JSONDecoder().decode(DrumKit.self, from: data) else { return DrumKit() }
        return kit.sanitized()
    }

    static func save(_ kit: DrumKit) {
        do {
            try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            try JSONEncoder().encode(kit).write(to: url, options: .atomic)
        } catch {
            // Not fatal: the kit simply isn't remembered this time.
        }
    }
}
